# F4 matrix runner (one OS x R row of .github/workflows/xplat-verify.yml). Base R + jsonlite only.
#
#   Rscript scripts/xplat/run-checks.R <xplat-out dir> <os label> <r label> <install path> <packages via>
# <packages via> is "renv" only when .github/r/restore.R restored and verified every locked version on this row.
#
# Runs, each in its own Rscript process (a failure never stops the others):
#   every check-<app>.R          -> ALMCHECK line + exit code per app
#   validation/entry/check_entry.R on <xplat-out>/entry/cases.json (generated by the export job)
#   PLANTED-check-<app>.R        -> must exit nonzero with passed < N ("planted detected")
#   every plots-<app>.R          -> PNGs into xplat-plots/
# and writes result-<os>-<r>.json. Exit status 1 if any check or the entry grid failed, a plots script
# failed, or the planted copy was NOT detected.
suppressPackageStartupMessages(library(jsonlite))
args <- commandArgs(trailingOnly = TRUE)
if (length(args) < 5L) stop("usage: run-checks.R <xplat-out> <os> <r> <install path> <packages via>")
out_dir <- args[[1]]; os <- args[[2]]; r_label <- args[[3]]; install <- args[[4]]; packages_via <- args[[5]]
rscript <- file.path(R.home("bin"), if (.Platform$OS.type == "windows") "Rscript.exe" else "Rscript")
log_dir <- "xplat-logs"
dir.create(log_dir, showWarnings = FALSE)

run <- function(script, extra = character(0), name = basename(script)) {
  out <- suppressWarnings(system2(rscript, c(shQuote(script), extra), stdout = TRUE, stderr = TRUE))
  status <- attr(out, "status"); if (is.null(status)) status <- 0L
  writeLines(out, file.path(log_dir, paste0(sub("\\.R$", "", name), ".log")))
  list(out = out, exit = as.integer(status))
}
count_line <- function(out, pattern) {
  m <- regmatches(out, regexec(pattern, out))
  m <- Filter(length, m)
  if (!length(m)) return(c(passed = NA_integer_, N = NA_integer_))
  last <- m[[length(m)]]
  c(passed = as.integer(last[[2]]), N = as.integer(last[[3]]))
}

manifest <- fromJSON(file.path(out_dir, "manifest.json"), simplifyVector = FALSE)
apps <- list()
for (a in manifest$apps) {
  app <- a$app
  r <- run(file.path(out_dir, paste0("check-", app, ".R")))
  n <- count_line(r$out, paste0("^ALMCHECK ", app, " ([0-9]+)/([0-9]+)\\s*$"))
  ok <- r$exit == 0L && !is.na(n[["N"]]) && n[["N"]] > 0L && n[["passed"]] == n[["N"]] && n[["N"]] == a$N
  apps[[app]] <- list(passed = n[["passed"]], N = n[["N"]], expected_N = a$N, exit = r$exit, pass = ok)
  cat(sprintf("%-22s %s  ALMCHECK %s/%s exit %d\n", app, if (ok) "PASS" else "FAIL", n[["passed"]], n[["N"]], r$exit))
  if (!ok) cat(paste0("    ", tail(r$out, 15)), sep = "\n")
}

entry_path <- file.path(out_dir, "entry", "cases.json")
er <- run(file.path("validation", "entry", "check_entry.R"), shQuote(entry_path), "entry")
en <- count_line(er$out, "^ENTRY ([0-9]+)/([0-9]+)\\s*$")
entry <- list(passed = en[["passed"]], N = en[["N"]], exit = er$exit,
  pass = er$exit == 0L && !is.na(en[["N"]]) && en[["N"]] >= 2000L && en[["passed"]] == en[["N"]])
cat(sprintf("%-22s %s  ENTRY %s/%s exit %d\n", "entry", if (entry$pass) "PASS" else "FAIL", en[["passed"]], en[["N"]], er$exit))

pl <- manifest$planted
planted <- list(app = pl$app, key = pl$key, detected = FALSE)
if (!is.null(pl)) {
  pr <- run(file.path(out_dir, pl$file))
  pn <- count_line(pr$out, paste0("^ALMCHECK ", pl$app, " ([0-9]+)/([0-9]+)\\s*$"))
  planted$passed <- pn[["passed"]]; planted$N <- pn[["N"]]; planted$exit <- pr$exit
  planted$detected <- pr$exit != 0L && !is.na(pn[["N"]]) && pn[["passed"]] < pn[["N"]]
}
cat(sprintf("%-22s %s  planted copy (%s) ALMCHECK %s/%s exit %s\n", "planted", if (planted$detected) "DETECTED" else "NOT DETECTED",
  pl$app, planted$passed, planted$N, planted$exit))

plots <- list()
for (a in manifest$apps) {
  r <- run(file.path(out_dir, paste0("plots-", a$app, ".R")))
  files <- sub("^PLOT ([^ ]+) *$", "\\1", grep("^PLOT ", r$out, value = TRUE))
  ok <- r$exit == 0L && length(files) == length(a$plots) && all(file.exists(file.path("xplat-plots", files)))
  plots[[a$app]] <- list(exit = r$exit, files = I(files), pass = ok)
  if (!ok) cat(sprintf("%-22s FAIL  plots exit %d\n", a$app, r$exit), paste0("    ", tail(r$out, 10)), sep = "\n")
}

pinned <- c("metafor", "meta", "netmeta", "metadat", "mada", "dosresmeta", "mvmeta", "mixmeta", "metasens",
  "robumeta", "clubSandwich", "jsonlite")
versions <- lapply(setNames(pinned, pinned), function(p) tryCatch(as.character(utils::packageVersion(p)), error = function(e) NULL))

n_apps <- length(apps); n_pass <- sum(vapply(apps, function(x) isTRUE(x$pass), logical(1)))
q_pass <- sum(vapply(apps, function(x) if (is.na(x$passed)) 0L else x$passed, integer(1)))
q_all <- sum(vapply(apps, function(x) as.integer(x$expected_N), integer(1)))
result <- list(os = os, r = r_label, R.version.string = R.version.string, platform = R.version$platform,
  install = install, packages_via = packages_via, packages = versions, apps = apps, checks = list(passed = n_pass, N = n_apps),
  quantities = list(passed = q_pass, N = q_all), entry = entry, planted = planted, planted_detected = planted$detected,
  plots = plots, plots_ok = all(vapply(plots, function(x) isTRUE(x$pass), logical(1))),
  export_commit = manifest$commit)
result$pass <- n_apps > 0L && n_pass == n_apps && isTRUE(entry$pass) && isTRUE(planted$detected) && isTRUE(result$plots_ok)
writeLines(toJSON(result, auto_unbox = TRUE, pretty = TRUE, null = "null", na = "null", digits = NA),
  sprintf("result-%s-%s.json", os, r_label))
cat(sprintf("XPLAT %s R %s: %d of %d checks pass (%d/%d quantities); entry %s/%s; planted %s; plots %s -> %s\n",
  os, r_label, n_pass, n_apps, q_pass, q_all, en[["passed"]], en[["N"]], if (planted$detected) "detected" else "NOT detected",
  if (result$plots_ok) "ok" else "FAILED", if (result$pass) "PASS" else "FAIL"))
quit(save = "no", status = if (result$pass) 0L else 1L)
